let category='All',cart=[];const money=n=>'৳'+Math.round(n).toLocaleString('en-BD');
function renderProducts(){let list=products.filter(p=>(category==='All'||p.category===category)&&(`${p.name} ${p.code}`.toLowerCase().includes(document.querySelector('#productSearch').value.toLowerCase())));const sort=document.querySelector('#sortProducts').value;if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);document.querySelector('#productGrid').innerHTML=list.length?list.map(p=>`<article class="product-card"><div class="product-image" style="background-image:url('${p.image}')"><div class="product-actions"><button onclick="addProduct(${p.id})">Add to list</button><button onclick="compareProduct(${p.id})">Compare</button></div></div><div class="product-info"><h3>${p.name}</h3><div class="product-meta"><span><i class="swatch" style="background:${p.color}"></i>${p.tone}</span><span>${p.code}</span></div><div class="product-price">${money(p.price)} / metre</div></div></article>`).join(''):'<div class="empty">No fabrics match your search. Try another name or code.</div>'}
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');category=b.dataset.category;renderProducts()});document.querySelectorAll('[data-filter-link]').forEach(a=>a.onclick=()=>{category=a.dataset.filterLink;document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.category===category));setTimeout(renderProducts,100)});document.querySelector('#productSearch').oninput=renderProducts;document.querySelector('#sortProducts').onchange=renderProducts;
const calcFabric=document.querySelector('#calcFabric');calcFabric.innerHTML=products.filter(p=>p.category!=='Ready to wear').map(p=>`<option value="${p.id}">${p.name} — ${money(p.price)}/m</option>`).join('');function calculate(){const p=products.find(x=>x.id==calcFabric.value),qty=Math.max(0,Number(document.querySelector('#calcQty').value)||0),unit=document.querySelector('#calcUnit').value;const metres=unit==='metre'?qty:qty*.9144,other=unit==='metre'?`${(qty*1.09361).toFixed(3)} yards`:`${metres.toFixed(3)} metres`,base=metres*p.price,vat=base*.05;document.querySelector('#convertedQty').textContent=other;document.querySelector('#basePrice').textContent=money(base);document.querySelector('#vatPrice').textContent=money(vat);document.querySelector('#totalPrice').textContent=money(base+vat)};['calcFabric','calcQty','calcUnit'].forEach(id=>document.querySelector('#'+id).oninput=calculate);
function addProduct(id,qty=1,unit='metre'){const p=products.find(x=>x.id==id);cart.push({...p,qty,unit});renderCart();toast(`${p.name} added to your fabric list`)}window.addProduct=addProduct;document.querySelector('#addCalcToCart').onclick=()=>addProduct(Number(calcFabric.value),Number(document.querySelector('#calcQty').value),document.querySelector('#calcUnit').value);function compareProduct(id){const p=products.find(x=>x.id===id);toast(`${p.name} saved for comparison`)}window.compareProduct=compareProduct;
function renderCart(){document.querySelector('#cartCount').textContent=cart.length;document.querySelector('#cartItems').innerHTML=cart.length?cart.map((x,i)=>`<div class="cart-item"><div class="cart-thumb" style="background-image:url('${x.image}')"></div><div><h4>${x.name}</h4><p>${x.qty} ${x.unit}${x.qty==1?'':'s'} · ${x.code}</p><strong>${money(x.price*x.qty*(x.unit==='yard'?.9144:1)*1.05)}</strong></div><button class="remove-item" onclick="removeItem(${i})">×</button></div>`).join(''):'<div class="empty">Your fabric list is empty.</div>';document.querySelector('#cartTotal').textContent=money(cart.reduce((s,x)=>s+x.price*x.qty*(x.unit==='yard'?.9144:1)*1.05,0))}window.removeItem=i=>{cart.splice(i,1);renderCart()};const drawer=document.querySelector('#cartDrawer'),scrim=document.querySelector('#scrim');function toggleCart(show){drawer.classList.toggle('open',show);scrim.classList.toggle('show',show);drawer.setAttribute('aria-hidden',!show)}document.querySelectorAll('[data-open-cart]').forEach(b=>b.onclick=()=>toggleCart(true));document.querySelector('#closeCart').onclick=()=>toggleCart(false);scrim.onclick=()=>toggleCart(false);document.querySelector('#printQuote').onclick=()=>window.print();document.querySelector('#requestQuote').onclick=()=>toast(cart.length?'Quotation request prepared — choose a showroom to continue.':'Add at least one fabric first.');
const locations=[{name:'Gulshan Showroom',address:'Gulshan Avenue, Dhaka',phone:'Showroom contact on request'},{name:'Dhanmondi Showroom',address:'Dhanmondi, Dhaka',phone:'Showroom contact on request'},{name:'Chattogram Showroom',address:'Chattogram',phone:'Showroom contact on request'}];function renderLocations(q=''){const f=locations.filter(l=>(l.name+l.address).toLowerCase().includes(q.toLowerCase()));document.querySelector('#locations').innerHTML=f.slice(0,2).map(l=>`<div class="location-card"><strong>${l.name}</strong><span>${l.address} · ${l.phone}</span></div>`).join('')||'<div class="location-card"><span>No demonstration locations matched.</span></div>'}document.querySelector('#locationSearch').oninput=e=>renderLocations(e.target.value);function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}renderProducts();renderLocations();calculate();renderCart();
